  AudioInput.SelectedItem=inputs.FirstOrDefault(x=>x.Id==settings.AudioInputId)??AudioDevices.Best(inputs);AudioOutput.SelectedItem=outputs.FirstOrDefault(x=>x.Id==settings.AudioOutputId)??AudioDevices.Best(outputs);
