 void DrawWaterfall()
 {
  if (WaterfallImage==null || WaterfallOverlay==null) return; int w=Math.Max(1,(int)WaterfallOverlay.ActualWidth), h=Math.Max(1,(int)WaterfallOverlay.ActualHeight); if(w<10||h<10)return;
  var pixels=new byte[w*h*4]; for(int y=0;y<h;y++) for(int x=0;x<w;x++){int i=(y*w+x)*4; byte v=(byte)(6+18*(h-y)/h); pixels[i]=v;pixels[i+1]=(byte)(v+7);pixels[i+2]=(byte)(v+14);pixels[i+3]=255;}
  var bmp=new WriteableBitmap(w,h,96,96,PixelFormats.Bgra32,null);bmp.WritePixels(new Int32Rect(0,0,w,h),pixels,w*4,0);WaterfallImage.Source=bmp;WaterfallOverlay.Children.Clear();
  for(int hz=0;hz<=3000;hz+=500){double x=hz/3000d*w;WaterfallOverlay.Children.Add(new Line{X1=x,X2=x,Y1=0,Y2=h,Stroke=new SolidColorBrush(Color.FromArgb(70,148,163,184))});var t=new TextBlock{Text=$"{hz} Hz",Foreground=Brushes.LightGray,FontSize=11};Canvas.SetLeft(t,Math.Min(x+3,w-50));Canvas.SetTop(t,3);WaterfallOverlay.Children.Add(t);}
 }
