 async void RefreshActivations(object s,RoutedEventArgs e)
 {
  FeedStatus.Text=L("Henter kataloger og SOTLAS-liveaktivitet …","Loading catalogues and SOTLAS live activity…");try{var fresh=await feeds.RefreshAsync();livePoints.Clear();livePoints.AddRange(fresh);UpdateMap();int pota=fresh.Count(x=>x.Program=="POTA"),sota=fresh.Count(x=>x.Program=="SOTA"),bota=fresh.Count(x=>x.Program=="BOTA"),spots=fresh.Count(x=>x.ActivityType=="LIVE SPOT"),alerts=fresh.Count(x=>x.ActivityType=="ALERT");FeedStatus.Text=Ft8AdvancedPanel.EnglishActive?$"Updated {DateTime.Now:HH:mm}: POTA {pota:N0} • SOTA {sota:N0} • BOTA {bota:N0}\nSOTLAS live: {spots} spots • {alerts} alerts • automatic every minute.":$"Oppdatert {DateTime.Now:HH:mm}: POTA {pota:N0} • SOTA {sota:N0} • BOTA {bota:N0}\nSOTLAS-live: {spots} spots • {alerts} alerts • automatisk hvert minutt.";}catch(Exception ex){FeedStatus.Text=L("Oppdatering feilet: ","Update failed: ")+ex.Message;}
 }
 void UpdateMap()
 {
  if(MapView==null)return;bool Enabled(string p)=>p switch{"POTA"=>ShowPota?.IsChecked==true,"BOTA"=>ShowBota?.IsChecked==true,"SOTA"=>ShowSota?.IsChecked==true,_=>false};var merged=points.Concat(livePoints).Where(x=>Enabled(x.Program)).GroupBy(x=>$"{x.Program}|{x.Reference}").Select(g=>g.First());MapView.SetMarkers(merged);GridTrackerMap?.SetQsoData(log,MyGrid.Text);UpdateActivatedMap();
 }
 void UpdateActivatedMap()
 {
  if(MapView==null)return;int Need(string p)=>p switch{"POTA"=>10,"SOTA"=>4,"BOTA"=>1,_=>int.MaxValue};var done=log.Where(q=>!string.IsNullOrWhiteSpace(q.Program)&&!string.IsNullOrWhiteSpace(q.Reference)).GroupBy(q=>$"{q.Program.ToUpperInvariant()}|{q.Reference.ToUpperInvariant()}").Where(g=>g.Count()>=Need(g.First().Program.ToUpperInvariant())).Select(g=>g.Key);MapView.SetActivated(done);
 }
}
